-- Idempotent install for processes.steps
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS processes;

CREATE SEQUENCE IF NOT EXISTS processes.steps_row_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS processes.steps (
    row_id integer NOT NULL,
    process_id integer NOT NULL,
    step_name text NOT NULL,
    step_type text NOT NULL,
    step_order text NOT NULL,
    expected_ms text NOT NULL,
    expected_rows text NOT NULL,
    id uuid DEFAULT gen_random_uuid(),
    timeout_ms integer DEFAULT 0 NOT NULL,
    duration_warn_pct numeric DEFAULT 0 NOT NULL,
    row_count_drift_pct numeric DEFAULT 0 NOT NULL,
    step_query text
);

ALTER TABLE processes.steps ALTER COLUMN row_id SET DEFAULT nextval('processes.steps_row_id_seq'::regclass);
ALTER SEQUENCE processes.steps_row_id_seq OWNED BY processes.steps.row_id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE processes.steps);
SELECT row_id, process_id, step_name, step_type, step_order, expected_ms, expected_rows, id, timeout_ms, duration_warn_pct, row_count_drift_pct, step_query FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM processes.steps);
DROP TABLE _stg_load;

SELECT setval('processes.steps_row_id_seq', GREATEST((SELECT COALESCE(max(row_id),0) FROM processes.steps),1), (SELECT count(*) FROM processes.steps) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'processes' AND c.relname = 'steps'
          AND con.conname = 'pk_steps') THEN
        ALTER TABLE ONLY processes.steps
    ADD CONSTRAINT pk_steps PRIMARY KEY (step_name, process_id);
    END IF;
END $do$;
